<?= $this->extend('shop/layout') ?>
<?= $this->section('content') ?>
<h1 class="h3"><?= esc($order['order_number']) ?></h1><p>Status pesanan: <strong><?= esc($order['order_status']) ?></strong><br>Status pembayaran: <strong><?= esc($payment['payment_status']) ?></strong><br>Terakhir diperbarui: <?= esc($order['updated_at']) ?> (pengguna #<?= esc($order['changed_by']) ?>)</p><div class="table-responsive"><table class="table"><thead><tr><th>Produk</th><th>Harga transaksi</th><th>Jumlah</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($items as $i): ?><tr><td><?= esc($i['product_name']) ?></td><td><?= esc($i['price']) ?></td><td><?= esc($i['quantity']) ?></td><td><?= esc($i['subtotal']) ?></td></tr><?php endforeach ?></tbody></table></div><p>Subtotal: Rp <?= esc($order['subtotal']) ?><br>Ongkir: Rp <?= esc($order['shipping_cost']) ?><br><strong>Total: Rp <?= esc($order['total']) ?></strong></p><?php $a=json_decode($order['address_snapshot'],true); ?><h2 class="h5">Alamat penerima</h2><p><?= esc($a['recipient_name']) ?> ? <?= esc($a['phone']) ?><br><?= esc($a['address'].', '.$a['city'].', '.$a['province'].' '.$a['postal_code']) ?></p>
