<?php if ($user['role']==='customer' && $order['order_status']==='pending_payment'): ?><div class="card p-4 mt-3"><h2 class="h5">Pembayaran manual</h2><p><?= esc(env('shop.bankInstructions','Hubungi toko untuk instruksi pembayaran.')) ?></p><form method="post" enctype="multipart/form-data" action="<?= site_url('orders/'.$order['id'].'/payment') ?>"><?= csrf_field() ?><label for="proof">Bukti pembayaran (JPEG/PNG, maksimal 2 MB)</label><input class="form-control my-2" type="file" id="proof" name="proof" accept="image/jpeg,image/png" required><button class="btn btn-primary">Kirim bukti</button></form></div><?php endif ?>
<?php if ($user['role']==='administrator' && in_array($order['order_status'],['pending_payment','waiting_verification'],true)): ?><form class="card p-4 mt-3" method="post" action="<?= site_url('admin/orders/'.$order['id'].'/status') ?>"><?= csrf_field() ?><label for="reason">Alasan penolakan (wajib saat menolak)</label><textarea class="form-control mb-3" id="reason" name="reason" maxlength="2000"></textarea><div class="d-flex gap-2 flex-wrap"><?php if ($order['order_status']==='waiting_verification'): ?><button class="btn btn-success" name="action" value="verify">Terima pembayaran</button><button class="btn btn-warning" name="action" value="reject">Tolak pembayaran</button><?php endif ?><button class="btn btn-outline-danger" name="action" value="cancel">Batalkan dan kembalikan stok</button></div></form><?php endif ?>
